inline int sequencePackChecks(){using namespace juce;auto root=File::getCurrentWorkingDirectory().getChildFile("Tests/ImportedFX-v09-Final/SynthHacker Free Presets");auto files=root.findChildFiles(File::findFiles,true,"*.SerumPreset");files.sort();auto owner=std::make_unique<SynthProcessor>();auto& p=*owner;int clips=0,audible=0;String csv="preset,clip_notes,arp_notes,automation_lanes,midi_note_ons,energy,peak\n";for(auto file:files){String error;if(!p.loadSerumPreset(file,root,error))return 291;p.prepareToPlay(48000,512);auto bank=p.sequences();int slot=bank->preview;if(bank->clips[slot].notes.empty()){for(int k=0;k<12;++k)if(!bank->clips[k].notes.empty()){slot=k;break;}}if(!bank->clips[slot].notes.empty())++clips;p.set("seqClipSlot",(float)slot);p.set("seqClipEnabled",1);p.set("seqMidiOut",2);p.clipRequest.store(slot);AudioBuffer<float> audio(2,512);MidiBuffer midi;double energy=0;float peak=0;int noteOns=0;for(int block=0;block<144;++block){midi.clear();p.processBlock(audio,midi);for(auto item:midi)noteOns+=item.getMessage().isNoteOn()?1:0;for(int c=0;c<2;++c)for(int i=0;i<512;++i){float value=audio.getSample(c,i);if(!std::isfinite(value)||std::abs(value)>1.001f)return 292;energy+=value*value;peak=jmax(peak,std::abs(value));}}if(energy>1.e-5)++audible;csv+='"'+file.getFileNameWithoutExtension()+"\","+String(bank->clips[slot].notes.size())+","+String(bank->arps[0].notes.size())+","+String(bank->clips[slot].lanes.size())+","+String(noteOns)+","+String(energy,7)+","+String(peak,7)+"\n";}auto folder=File::getCurrentWorkingDirectory().getChildFile("Tests/Sequencer");folder.createDirectory();folder.getChildFile("Pack-Clip-Playback.csv").replaceWithText(csv);std::cout<<"PASS: "<<files.size()<<" presets, "<<clips<<" stored clips, "<<audible<<" audible clip/arp renders, finite bounded audio. Original sound equivalence not tested.\n";return files.size()==71?0:293;
}
